import json
with open('/app/resources/treasury_bulletin_1972_04.json', 'r') as f:
    data = json.load(f)

if 'document' in data and 'elements' in data['document']:
    elements = data['document']['elements']
    count = 0
    for el in elements:
        if isinstance(el, dict):
            if 'table' in el:
                count += 1
                if count < 5:
                    print('Table found, keys:', list(el.keys()))
                    if 'metadata' in el and el['metadata']:
                        print('metadata:', el['metadata'])
                    if 'caption' in el:
                        print('caption:', el['caption'])
    print('Total tables:', count)
"
